PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=10000;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,passwordHash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','manager','driver','passenger')),phone TEXT DEFAULT '',discountType TEXT DEFAULT '',discountStatus TEXT DEFAULT 'none',discountEvidence TEXT DEFAULT '',active INTEGER NOT NULL DEFAULT 1,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(tokenHash TEXT PRIMARY KEY,userId INTEGER NOT NULL REFERENCES users(id),expiresAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stops(id INTEGER PRIMARY KEY,name TEXT NOT NULL,address TEXT DEFAULT '',lat REAL NOT NULL,lng REAL NOT NULL);
CREATE TABLE IF NOT EXISTS routes(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,origin TEXT NOT NULL,destination TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),durationMinutes INTEGER NOT NULL CHECK(durationMinutes>0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS route_stops(routeId INTEGER NOT NULL REFERENCES routes(id),stopId INTEGER NOT NULL REFERENCES stops(id),stopOrder INTEGER NOT NULL,PRIMARY KEY(routeId,stopId));
CREATE TABLE IF NOT EXISTS buses(id INTEGER PRIMARY KEY,plate TEXT NOT NULL UNIQUE,name TEXT NOT NULL,seatCount INTEGER NOT NULL CHECK(seatCount BETWEEN 1 AND 80),status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS trips(id INTEGER PRIMARY KEY,routeId INTEGER NOT NULL REFERENCES routes(id),busId INTEGER NOT NULL REFERENCES buses(id),driverId INTEGER NOT NULL REFERENCES users(id),departureTime TEXT NOT NULL,arrivalTime TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled',lat REAL,lng REAL,locationUpdatedAt TEXT,locationSource TEXT DEFAULT 'unavailable');
CREATE TABLE IF NOT EXISTS vouchers(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE COLLATE NOCASE,percent INTEGER NOT NULL,maxDiscount INTEGER NOT NULL,expiresAt TEXT NOT NULL,usageLimit INTEGER NOT NULL,usedCount INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY,userId INTEGER NOT NULL REFERENCES users(id),tripId INTEGER NOT NULL REFERENCES trips(id),seat INTEGER NOT NULL,status TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),code TEXT NOT NULL UNIQUE,holdExpiresAt TEXT,paymentMethod TEXT DEFAULT '',refundStatus TEXT NOT NULL DEFAULT 'none',createdAt TEXT NOT NULL,paidAt TEXT,voucherId INTEGER REFERENCES vouchers(id));
CREATE UNIQUE INDEX IF NOT EXISTS occupied_seat ON tickets(tripId,seat) WHERE status IN('held','paid','checked_in');
CREATE INDEX IF NOT EXISTS tickets_user ON tickets(userId);
CREATE INDEX IF NOT EXISTS trips_departure ON trips(departureTime);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,ticketId INTEGER NOT NULL REFERENCES tickets(id),userId INTEGER NOT NULL REFERENCES users(id),amount INTEGER NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,createdAt TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_successful_payment ON payments(ticketId) WHERE status IN('paid','refunded');
CREATE TABLE IF NOT EXISTS refunds(id INTEGER PRIMARY KEY,ticketId INTEGER NOT NULL UNIQUE REFERENCES tickets(id),amount INTEGER NOT NULL,status TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS passes(id INTEGER PRIMARY KEY,userId INTEGER NOT NULL REFERENCES users(id),routeId INTEGER NOT NULL REFERENCES routes(id),startDate TEXT NOT NULL,endDate TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents(id INTEGER PRIMARY KEY,tripId INTEGER NOT NULL REFERENCES trips(id),driverId INTEGER NOT NULL REFERENCES users(id),type TEXT NOT NULL,description TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY,userId INTEGER NOT NULL REFERENCES users(id),tripId INTEGER NOT NULL REFERENCES trips(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),message TEXT NOT NULL,response TEXT DEFAULT '',status TEXT DEFAULT 'open',createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,userId INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,message TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,createdAt TEXT NOT NULL,dedupeKey TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,userId INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entityId TEXT,details TEXT DEFAULT '',createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY,userId INTEGER NOT NULL REFERENCES users(id),ticketId INTEGER NOT NULL REFERENCES tickets(id),recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
